// Estrutura do Cache de Histórico (Undo / Redo com teto global configurável de 10MB a 2000MB)
struct HistoryPatch {
    int x = 0, y = 0, w = 0, h = 0;
    // Patch de histórico em BGRA 32-bit, armazenado de cima para baixo.
    std::vector<BYTE> pixelData;
};
struct HistoryState {
    std::vector<BYTE> pixelData; // snapshot inteiro (ações não-pincel)
    std::vector<HistoryPatch> patches; // apenas regiões alteradas por lápis/borracha
    int largura = 0;
    int altura = 0;
    int layerIndex = 0;
    bool partial = false;
    size_t cacheBytes = 0; // payload de pixels, O(1) para contabilizar o histórico
    unsigned long long serial = 0; // ordenação global do histórico
};

// Histórico do canvas/timeline: limite de ações e teto de memória configuráveis.
// Padrão: 20 ações por quadro e 200 MB de cache GLOBAL, persistidos em Documentos\Kodanima\config.ini.
int historyActionLimit = 20;
int historyCacheLimitMB = 200;
static unsigned long long g_historySerialCounter = 1;

struct FrameData {
    int id;
    double segundos = 1.0;
    int unidadeDuracao = 1; // 0=minutos, 1=segundos
    HBITMAP hBmpQuadro = NULL;
    std::list<HistoryState> undoStack;
    std::list<HistoryState> redoStack;
    size_t cacheMemoryUsageBytes = 0;
    std::vector<HBITMAP> layerBitmaps; // bitmaps independentes por camada; hBmpQuadro aponta para a camada ativa
    std::vector<double> layerDurations; // duração independente por camada neste quadro
    std::vector<bool> layerFrameExists; // quadro existe apenas nas camadas marcadas como true
};

