struct KodaProjectMediaAsset {
    std::wstring name; // nome original exibido na timeline e salvo no project.json
    std::wstring relativePath;
    std::wstring type; // image, audio, video ou gif
    double startSeconds = 0.0;
    double durationSeconds = 0.0;
    int frame = 0;
    int layer = 0;
    int x = 0;
    int y = 0;
    // Quadros decodificados em assets/<arquivo>.<ext>.frames para preview/exportação
    // sem manter a animação inteira na RAM.
    int decodedFrames = 0;
    double decodedFps = 0.0;
    int decodedCacheVersion = 0; // 0 = cache antiga ou versão desconhecida
    // PTS relativos ao primeiro quadro, lidos do próprio fluxo quando disponíveis.
    // Vazio significa usar decodedFps como fallback compatível com projetos antigos.
    std::vector<double> decodedFrameTimes;
    int decodeEngineMode = 1; // 1 = FFmpeg; 2 = VLC/LibVLC; 0 = legacy native cache
    int rendererMode = 0; // 0 = conversão para PNG; 1 = prévia nativa sob demanda
    int opacityPercent = 100; // opacidade do vídeo/GIF de referência no canvas
    // Transformações ficam no clipe: nunca alteram os pixels originais do vídeo.
    double scalePercent = 100.0;       // escala uniforme do clipe
    double rotationDegrees = 0.0;      // rotação manual do clipe
    double sourceRotationDegrees = 0.0; // orientação declarada pelo vídeo; separada da rotação do usuário
    // Resolução real dos quadros armazenados; a prévia do canvas é escalada à parte.
    UINT32 sourceWidth = 0, sourceHeight = 0;
    UINT32 pixelAspectX = 1, pixelAspectY = 1;
    int audioTrackIndex = -1; // faixa especial de áudio independente; -1 para outros tipos
    int audioVolumePercent = 100; // volume individual desta faixa (0-100)
    bool audioMuted = false;     // silenciar sem excluir a faixa
    int audioQualityMode = 0;    // 0=PCM na taxa nativa; 1=PCM estéreo 48 kHz; 2=compatibilidade MCI
    std::vector<float> waveformPeaks; // cache de forma de onda da prévia, não serializada
};
