static int KodaVideoAssetSelecionadoOuUltimo() {
    if(g_selectedMediaAssetIndex>=0 && g_selectedMediaAssetIndex<(int)g_projectMediaAssets.size()) {
        const auto& a=g_projectMediaAssets[(size_t)g_selectedMediaAssetIndex];
        if(a.type==L"video" || a.type==L"gif") return g_selectedMediaAssetIndex;
    }
    for(int i=(int)g_projectMediaAssets.size()-1;i>=0;--i)
        if(g_projectMediaAssets[(size_t)i].type==L"video" || g_projectMediaAssets[(size_t)i].type==L"gif") return i;
    return -1;
}
