static double KodaTimelinePixelsPerSecond() {
    // O zoom altera somente a representação horizontal, não a duração nem o FPS.
    const double zoom = std::max(0.25, std::min(16.0, timelineVisualZoom));
    return (timelineLayoutMode==1 ? 25.0 : 46.0) * zoom;
}
// Conversão única para TODAS as faixas: régua, desenho, áudio e vídeo compartilham
// exatamente a mesma origem e a mesma escala em segundos.
static int KodaTimelineXFromSeconds(double seconds) {
    const double px=KodaTimelinePixelsPerSecond();
    return TIMELINE_SPLIT_X+(int)std::lround((seconds-(double)timelineScrollSeconds)*px);
}
static double KodaTimelineSecondsFromX(int x) {
    const double px=std::max(0.001,KodaTimelinePixelsPerSecond());
    return (double)timelineScrollSeconds+((double)x-(double)TIMELINE_SPLIT_X)/px;
}
