static bool KodaMediaAssetSelecionadoEmGrupo(int index) { return std::find(g_selectedMediaAssets.begin(), g_selectedMediaAssets.end(), index) != g_selectedMediaAssets.end(); }
static void KodaSelecionarMediaAsset(int index, bool shift) {
    if(index<0 || index>=(int)g_projectMediaAssets.size()) {
        if(!shift) g_selectedMediaAssets.clear();
        g_selectedMediaAssetIndex=-1;
        return;
    }
    if(!shift) g_selectedMediaAssets.clear();
    // Shift é aditivo (padrão de seleção múltipla): não removemos o clipe já
    // selecionado no mouse-down, pois isso desfazia o grupo antes de começar a arrastar.
    if(!KodaMediaAssetSelecionadoEmGrupo(index)) g_selectedMediaAssets.push_back(index);
    g_selectedMediaAssetIndex=index;
}
static void KodaIniciarArrasteGrupoMedia(int anchor) {
    g_groupMediaDragStarts.clear(); g_groupMediaDragging=false;
    if(!KodaMediaAssetSelecionadoEmGrupo(anchor)) { g_selectedMediaAssets.clear(); g_selectedMediaAssets.push_back(anchor); }
    for(int i:g_selectedMediaAssets) if(i>=0 && i<(int)g_projectMediaAssets.size()) g_groupMediaDragStarts.push_back({i,g_projectMediaAssets[i].startSeconds});
    g_groupMediaDragAnchorStart=(anchor>=0 && anchor<(int)g_projectMediaAssets.size())?g_projectMediaAssets[anchor].startSeconds:0.0;
    g_groupMediaDragging=g_groupMediaDragStarts.size()>1;
}
static int KodaCategoriaAtalho(int i) {
    if(i==0 || i==1 || i==2 || i==4 || i==6 || i==8 || i==9 || i==16 || i==17 || i==18 || i==19 || (i>=22 && i<=25) || i==29) return 1;
    if(i==5 || i==11 || i==12 || i==13 || i==14 || i==15 || i==20 || i==21 || i==26 || i==28 || i==3 || i==10) return 2;
    if(i==27) return 3;
    return 2;
}
static int KodaIndiceAtalhoVisivel(int row) { return row>=0 && row<g_shortcutVisibleCount ? g_shortcutVisibleIndices[row] : -1; }
