bool estabilizadorTracoAtivo = true;
int nivelEstabilizadorTraco = 35;
// O estabilizador usa uma pequena janela de amostras, como a fila de posições
// usada pelo Krita. O ponto bruto fica separado do ponto já suavizado para que
// movimentos curtos não sejam confundidos com eventos repetidos.
static std::vector<POINT> g_kodaStabilizerHistory;
static POINT g_kodaStabilizerLastRawPoint={0,0};
static bool g_kodaStabilizerRawValid=false;
static bool g_kodaStabilizerFinishing=false;
static int g_kodaStabilizerWindow=0;
static int KodaTamanhoJanelaEstabilizador(int level) {
    const int v=std::max(0,std::min(100,level));
    return 3+(v*9+50)/100; // 3 a 12 amostras; mais nível = mais estabilização
}
static void KodaIniciarEstabilizadorTraco(POINT initial) {
    g_kodaStabilizerHistory.clear();
    g_kodaStabilizerLastRawPoint=initial;
    g_kodaStabilizerRawValid=true;
    g_kodaStabilizerWindow=0;
    if(!estabilizadorTracoAtivo || nivelEstabilizadorTraco<=0) return;
    const int count=KodaTamanhoJanelaEstabilizador(nivelEstabilizadorTraco);
    try {
        g_kodaStabilizerHistory.assign((size_t)count,initial);
        g_kodaStabilizerWindow=count;
    } catch(...) {
        g_kodaStabilizerHistory.clear();
        g_kodaStabilizerWindow=0;
        g_kodaStabilizerRawValid=false;
    }
}
static POINT KodaFiltrarPontoEstabilizador(POINT raw) {
    if(!estabilizadorTracoAtivo || nivelEstabilizadorTraco<=0) return raw;
    if(!g_kodaStabilizerRawValid || g_kodaStabilizerHistory.empty()) {
        KodaIniciarEstabilizadorTraco(raw);
        return raw;
    }
    const int wanted=KodaTamanhoJanelaEstabilizador(nivelEstabilizadorTraco);
    try {
        while((int)g_kodaStabilizerHistory.size()>wanted)
            g_kodaStabilizerHistory.erase(g_kodaStabilizerHistory.begin());
        while((int)g_kodaStabilizerHistory.size()<wanted) {
            const POINT oldest=g_kodaStabilizerHistory.front();
            g_kodaStabilizerHistory.insert(g_kodaStabilizerHistory.begin(),oldest);
        }
        g_kodaStabilizerHistory.push_back(raw);
        while((int)g_kodaStabilizerHistory.size()>wanted)
            g_kodaStabilizerHistory.erase(g_kodaStabilizerHistory.begin());
        g_kodaStabilizerWindow=wanted;
        g_kodaStabilizerLastRawPoint=raw;
        long long sumX=0,sumY=0;
        for(const POINT& q:g_kodaStabilizerHistory) { sumX+=(long long)q.x; sumY+=(long long)q.y; }
        const double n=(double)g_kodaStabilizerHistory.size();
        POINT out={(LONG)std::lround((double)sumX/n),(LONG)std::lround((double)sumY/n)};
        return out;
    } catch(...) {
        g_kodaStabilizerHistory.clear();
        g_kodaStabilizerWindow=0;
        g_kodaStabilizerRawValid=false;
        g_kodaStabilizerLastRawPoint=raw;
        return raw;
    }
}
static void KodaLimparEstadoEstabilizadorTraco() {
    g_kodaStabilizerHistory.clear();
    g_kodaStabilizerWindow=0;
    g_kodaStabilizerRawValid=false;
    g_kodaStabilizerFinishing=false;
}
int durezaPincel = 2; // Padrão estético: Firme. 0 Macio, 1 Suave, 2 Firme, 3 Duro, 4 Pixel
int intensidadeAntiAlias = 70; // 1-100: intensidade do efeito no modo selecionado
// Perfil de cobertura por modo: Firme mantém o centro sólido e uma borda AA curta,
// evitando o aspecto lavado de uma faixa de suavização demasiado larga.
static double KodaPincelFeather(int dureza, int intensidade) {
    const int h=std::max(0,std::min(4,dureza));
    const double strength=std::sqrt((double)std::max(1,std::min(100,intensidade))/100.0);
    switch(h) {
        case 0: return 4.40*strength+0.65; // Macio: halo amplo e desfocado
        case 1: return std::max(1.10,1.55*strength+0.18); // Suave: borda limpa, mas visivelmente suavizada
        case 2: return std::max(0.65,0.92*strength+0.16); // Firme: antialias padrão de desenho digital
        case 3: return 0.22*strength+0.025; // Duro: transição mínima, serrilhado crescente
        default: return 0.0; // Pixel: sem cobertura intermediária
    }
}
// Perfis de cobertura: Macio gaussiano, Suave com curva smoothstep, Firme
// com cobertura AA normal, Duro com franja mínima e Pixel com borda binária.
static double KodaCoberturaAntiAlias(double dist,double radius,double feather,int dureza) {
    if(dureza>=4) return dist<=radius ? 1.0 : 0.0;
    const double maxDist=radius+feather*0.5;
    if(feather<=0.0001 || dist>=maxDist) return 0.0;
    if(dureza==0) {
        const double coreRadius=std::max(0.0,radius-feather*0.5);
        const double span=std::max(0.001,maxDist-coreRadius);
        const double t=std::max(0.0,std::min(1.0,(dist-coreRadius)/span));
        // Gradiente gaussiano de halo em vez de só uma borda pouco suave.
        return std::max(0.0,std::min(1.0,std::exp(-3.2*t*t)*(1.0-t*t)));
    }
    if(dureza==1) {
        const double coreRadius=std::max(0.0,radius-feather*0.5);
        const double span=std::max(0.001,maxDist-coreRadius);
        const double t=std::max(0.0,std::min(1.0,(dist-coreRadius)/span));
        return 1.0-t*t*(3.0-2.0*t);
    }
    if(dureza==2) {
        // Firme: borda de antialias de aproximadamente um pixel, centrada no raio.
        // Preserva o núcleo sólido mesmo em traços finos, sem aspecto cinza/desfocado.
        const double edge=std::max(0.60,std::min(1.20,feather));
        const double t=std::max(0.0,std::min(1.0,(radius+edge*0.5-dist)/edge));
        return t*t*(3.0-2.0*t);
    }
    return std::max(0.0,std::min(1.0,(maxDist-dist)/std::max(0.001,feather)));
}
