// Perfil automático: CPU/RAM determinam o mínimo seguro. Depois disso, a marca Celeron
// recebe o perfil Extremo conforme pedido pelo usuário; outras famílias usam núcleo/RAM.
static int KodaQualidadeAutomaticaCPU() {
    // CPU/RAM mudam raramente; detectar uma vez evita chamadas de sistema a cada WM_PAINT.
    static int qualidadeCacheada=-1;
    if(qualidadeCacheada>=0) return qualidadeCacheada;
    SYSTEM_INFO si{}; GetSystemInfo(&si);
    const DWORD cores=std::max<DWORD>(1,si.dwNumberOfProcessors);
    MEMORYSTATUSEX mem{}; mem.dwLength=sizeof(mem);
    unsigned long long ramMB=0;
    if(GlobalMemoryStatusEx(&mem)) ramMB=(unsigned long long)(mem.ullTotalPhys/(1024ull*1024ull));
    // Um processador realmente antigo de 1 núcleo ou RAM muito baixa sempre privilegia fluidez.
    if(cores<=1 || (ramMB && ramMB<=2048ull)) return qualidadeCacheada=0; // Nano
    // A marca Celeron por si só não distingue gerações; só aplica o perfil pedido
    // pelo usuário depois de excluir máquinas com núcleo único/até 2 GB de RAM.
    if(wcsstr(g_kodaCPU.brand,L"Celeron") || wcsstr(g_kodaCPU.brand,L"CELERON")) return qualidadeCacheada=3;
    if(cores<=2 || (ramMB && ramMB<=4096ull)) return qualidadeCacheada=1; // Médio
    if(cores<=4 || (ramMB && ramMB<=8192ull)) return qualidadeCacheada=2; // Full
    return qualidadeCacheada=3; // Extremo
}
static int KodaQualidadeOnionEfetiva() {
    if(!g_onionOptimizationEnabled) return 3;
    return g_onionQualityMode==0 ? KodaQualidadeAutomaticaCPU() : std::max(0,std::min(3,g_onionQualityMode-1));
}
static int KodaQualidadeCanvasEfetiva() {
    if(!g_canvasOptimizationEnabled) return 3;
    return g_canvasQualityMode==0 ? KodaQualidadeAutomaticaCPU() : std::max(0,std::min(3,g_canvasQualityMode-1));
}
static const wchar_t* KodaQualidadeModoRotulo(int mode) {
    static const wchar_t* labels[]={L"Automática (CPU/RAM)",L"Nano — máximo desempenho",L"Médio — equilibrado",L"Full — alta qualidade",L"Extremo — qualidade máxima"};
    return labels[std::max(0,std::min(4,mode))];
}
