// Metas somente para a navegação do canvas. Não limitam a fila de entrada do mouse/caneta
// nem as pinceladas; reduzem a frequência de pinturas para impedir que Space+arrasto
// monopolize o thread de UI em máquinas fracas. 0=automático, 1=20, 2=35, 3=60, 4=90.
static int g_canvasPanCpuBudgetMode = 0;
static int g_canvasPanGpuBudgetMode = 0; // orçamento gráfico indireto por cadência de quadros
static DWORD g_canvasPanLastPaintTick = 0;
static double g_canvasPanLastPaintCostMs = 8.0;
static bool g_canvasPanFrameQueued = false;
// Evita empilhar invalidações e recalcular seleções grandes em cada evento de pan.
static bool g_canvasPanPaintPending = false;
static bool g_canvasPanSelectionNeedsUpdate = false;
static int KodaPercentualModoPan(int mode) {
    switch(mode) { case 1:return 20; case 2:return 35; case 3:return 60; case 4:return 90; default:return 0; }
}
static DWORD KodaIntervaloGraficoPanMs() {
    switch(g_canvasPanGpuBudgetMode) {
        case 1: return 83;  // aproximadamente 12 FPS
        case 2: return 48;  // aproximadamente 21 FPS
        case 3: return 28;  // aproximadamente 36 FPS
        case 4: return 19;  // aproximadamente 54 FPS
        default: return InterlockedCompareExchange(&g_kodaPerfHighLoad,0,0)?33:17; // automático: 30/60 FPS
    }
}
static DWORD KodaAtrasoProximoQuadroPanMs() {
    const double workMs=std::max(1.0,std::min(250.0,g_canvasPanLastPaintCostMs));
    const bool systemBusy=InterlockedCompareExchange(&g_kodaPerfHighLoad,0,0)!=0;
    const int cpuPercent=KodaPercentualModoPan(g_canvasPanCpuBudgetMode);
    // Meta de CPU é um orçamento aproximado do tempo gasto redesenhando a vista.
    // A entrada do mouse é processada imediatamente; só o próximo quadro visual aguarda.
    // Automático mira ~90% da cadência de desenho em repouso e ~60% sob carga.
    // O monitor de sistema pode levar até um segundo para detectar a saturação, então
    // esta margem evita manter a interface ocupada a 100% durante esse intervalo.
    const double cpuWaitMs=cpuPercent>0 ? workMs*((100.0-cpuPercent)/(double)cpuPercent)
                                       : workMs*(systemBusy?0.65:0.12);
    const double graphicsWaitMs=std::max(0.0,(double)KodaIntervaloGraficoPanMs()-workMs);
    const double waitMs=std::max(cpuWaitMs,graphicsWaitMs);
    return (DWORD)std::max(1.0,std::min(1000.0,std::ceil(waitMs)));
}
static void KodaSolicitarQuadroPan(HWND hwnd) {
    if(!hwnd || !IsWindow(hwnd)) return;
    // Um WM_PAINT já solicitado vai desenhar o estado mais recente de panX/panY.
    // Ignorar invalidações repetidas de mouse evita que pan rápido encha o thread de UI.
    if(g_canvasPanPaintPending) return;
    if(!g_canvasUseFastNavigationQuality) {
        g_canvasPanPaintPending=true;
        InvalidateRect(hwnd,NULL,FALSE);
        return;
    }
    const DWORD now=GetTickCount();
    const DWORD delay=KodaAtrasoProximoQuadroPanMs();
    const DWORD elapsed=g_canvasPanLastPaintTick?(DWORD)(now-g_canvasPanLastPaintTick):delay;
    if(elapsed>=delay) {
        if(g_canvasPanFrameQueued) KillTimer(hwnd,ID_TIMER_CANVAS_NAV_FRAME);
        g_canvasPanFrameQueued=false;
        g_canvasPanPaintPending=true;
        InvalidateRect(hwnd,NULL,FALSE);
    } else if(!g_canvasPanFrameQueued) {
        const DWORD remaining=std::max<DWORD>(1,delay-elapsed);
        if(SetTimer(hwnd,ID_TIMER_CANVAS_NAV_FRAME,remaining,NULL)!=0) g_canvasPanFrameQueued=true;
        else {
            // Fallback de segurança: atualiza o canvas se o Windows não criar o timer.
            g_canvasPanPaintPending=true;
            InvalidateRect(hwnd,NULL,FALSE);
        }
    }
}
