static void KodaDefinirTimerPreviewAltaResolucao(bool enable) {
    using TimerPeriodFn=UINT (WINAPI *)(UINT);
    if(enable) {
        if(g_kodaPreviewTimerHighRes) return;
        if(!g_kodaWinmmTimerModule) g_kodaWinmmTimerModule=LoadLibraryW(L"winmm.dll");
        if(g_kodaWinmmTimerModule) {
            TimerPeriodFn begin=(TimerPeriodFn)GetProcAddress(g_kodaWinmmTimerModule,"timeBeginPeriod");
            if(begin && begin(1)==0) g_kodaPreviewTimerHighRes=true;
            else { FreeLibrary(g_kodaWinmmTimerModule); g_kodaWinmmTimerModule=NULL; }
        }
    } else {
        if(g_kodaPreviewTimerHighRes && g_kodaWinmmTimerModule) {
            TimerPeriodFn end=(TimerPeriodFn)GetProcAddress(g_kodaWinmmTimerModule,"timeEndPeriod");
            if(end) end(1);
        }
        g_kodaPreviewTimerHighRes=false;
        if(g_kodaWinmmTimerModule) { FreeLibrary(g_kodaWinmmTimerModule); g_kodaWinmmTimerModule=NULL; }
    }
}
