static std::wstring KodaNomeIdiomaVisivel(const wchar_t* code, const wchar_t* nativeName) {
    const std::wstring c = code ? code : L"";
    // Nomes em caracteres latinos evitam que versões do Windows sem a fonte do idioma
    // mostrem apenas traços/quadrados na lista. O idioma selecionado continua sendo o mesmo.
    static const std::map<std::wstring,std::wstring> nomes = {
        {L"ru",L"Russian"},{L"uk",L"Ukrainian"},{L"be",L"Belarusian"},{L"bg",L"Bulgarian"},
        {L"sr",L"Serbian"},{L"el",L"Greek"},{L"az",L"Azerbaijani"},{L"kk",L"Kazakh"},
        {L"uz",L"Uzbek"},{L"ky",L"Kyrgyz"},{L"hy",L"Armenian"},{L"ka",L"Georgian"},
        {L"mk",L"Macedonian"},{L"ar",L"Arabic"},{L"he",L"Hebrew"},{L"fa",L"Persian"},
        {L"ur",L"Urdu"},{L"ps",L"Pashto"},{L"hi",L"Hindi"},{L"bn",L"Bengali"},
        {L"pa",L"Punjabi"},{L"gu",L"Gujarati"},{L"mr",L"Marathi"},{L"ne",L"Nepali"},
        {L"si",L"Sinhala"},{L"ta",L"Tamil"},{L"te",L"Telugu"},{L"kn",L"Kannada"},
        {L"ml",L"Malayalam"},{L"or",L"Odia"},{L"as",L"Assamese"},{L"zh-CN",L"Chinese (Simplified)"},
        {L"zh-TW",L"Chinese (Traditional)"},{L"ja",L"Japanese"},{L"ko",L"Korean"},
        {L"th",L"Thai"},{L"am",L"Amharic"},{L"km",L"Khmer"},{L"my",L"Burmese"},
        {L"lo",L"Lao"},{L"mn",L"Mongolian"},{L"bo",L"Tibetan"}
    };
    auto it = nomes.find(c);
    return it != nomes.end() ? it->second : std::wstring(nativeName ? nativeName : L"");
}

static std::wstring KodaIdiomaBase() {
    size_t p=g_languageCode.find(L'-');
    return p==std::wstring::npos?g_languageCode:g_languageCode.substr(0,p);
}

