    png.clear(); png.reserve(zlibSize+57u);
    const BYTE sig[8]={137,80,78,71,13,10,26,10};png.insert(png.end(),sig,sig+8);
    std::vector<BYTE> ihdr;AppendBE32(ihdr,(unsigned long)w);AppendBE32(ihdr,(unsigned long)h);ihdr.push_back(8);ihdr.push_back(6);ihdr.push_back(0);ihdr.push_back(0);ihdr.push_back(0);PNGChunk(png,"IHDR",ihdr);
