                int mediaRows=std::max<int>(1,static_cast<int>(KodaContarAssetsTipo(L"audio")))+1;
                int maxRows=std::max(0,(int)timelineLayers.size()+mediaRows-visibleRows);
                int step=(GET_WHEEL_DELTA_WPARAM(wParam)>0)?-1:1;
