                { std::wstring label=KodaTraduzirTexto(L"Excluir"); DrawTextW(dis->hDC,label.c_str(),-1,(LPRECT)&dis->rcItem,DT_CENTER|DT_VCENTER|DT_SINGLELINE|DT_END_ELLIPSIS); }
